const messageText = $('Extract Message Data').first().json.messageText.toLowerCase().trim();
const userData = $input.item.json;

// Get the _id from MongoDB result
const userId = userData._id;
const phoneNumber = userData.phoneNumber;

// Initialize response
let responseMessage = "";
let shouldUpdate = false;

// Object to store ONLY the fields that need updating
const fieldsToUpdate = {};

// Parse different update commands
try {
  // Command: UPDATE DESIGNATION <new_designation>
  if (messageText.includes("update designation")) {
    const match = messageText.match(/update designation[:\s]+(.+)/i);
    if (match && match[1]) {
      fieldsToUpdate.designation = match[1].trim();
      responseMessage = `✅ Designation updated to: ${match[1].trim()}`;
      shouldUpdate = true;
    }
  }

  // Command: UPDATE EMAIL <new_email>
  else if (messageText.includes("update email")) {
    const emailMatch = messageText.match(/([\w.+-]+@[\w.-]+\.[a-zA-Z]{2,})/i);
    if (emailMatch && emailMatch[1]) {
      fieldsToUpdate.email = emailMatch[1];
      responseMessage = `✅ Email updated to: ${emailMatch[1]}`;
      shouldUpdate = true;
    } else {
      responseMessage = "❌ Invalid email format. Use: UPDATE EMAIL your@email.com";
    }
  }

  // Command: UPDATE NAME <new_name>
  else if (messageText.includes("update name")) {
    const match = messageText.match(/update name[:\s]+(.+)/i);
    if (match && match[1]) {
      fieldsToUpdate.name = match[1].trim();
      responseMessage = `✅ Name updated to: ${match[1].trim()}`;
      shouldUpdate = true;
    }
  }

  // Command: UPDATE STATUS <new_status>
  else if (messageText.includes("update status")) {
    const match = messageText.match(/update status[:\s]+(.+)/i);
    if (match && match[1]) {
      const status = match[1].trim().toLowerCase();
      if (["active", "inactive", "pending"].includes(status)) {
        fieldsToUpdate.status = status;
        responseMessage = `✅ Status updated to: ${status}`;
        shouldUpdate = true;
      } else {
        responseMessage = "❌ Invalid status. Use: active, inactive, or pending";
      }
    }
  }

  // Command: UPDATE FIELD <fieldname> <value>
  else if (messageText.startsWith("update field")) {
    const match = messageText.match(/update field[:\s]+(\w+)[:\s]+(.+)/i);
    if (match && match[1] && match[2]) {
      const fieldName = match[1].trim();
      const fieldValue = match[2].trim();
      fieldsToUpdate[fieldName] = fieldValue;
      responseMessage = `✅ ${fieldName} updated to: ${fieldValue}`;
      shouldUpdate = true;
    }
  }

  // Command: HELP
  else if (messageText === "help" || messageText === "commands") {
    responseMessage = `📋 *Available Commands:*\n\n` +
      `1️⃣ UPDATE DESIGNATION <value>\n` +
      `2️⃣ UPDATE EMAIL <email>\n` +
      `3️⃣ UPDATE NAME <name>\n` +
      `4️⃣ UPDATE STATUS <active/inactive/pending>\n` +
      `5️⃣ UPDATE FIELD <fieldname> <value>\n` +
      `6️⃣ SHOW INFO - View your profile\n` +
      `7️⃣ HELP - Show this message\n\n` +
      `Example: UPDATE DESIGNATION Senior Developer`;
  }

  // Command: SHOW INFO
  else if (messageText === "show info" || messageText === "my info") {
    responseMessage = `👤 *Your Profile:*\n\n` +
      `📱 Phone: ${userData.phoneNumber || 'N/A'}\n` +
      `👨‍💼 Name: ${userData.name || 'N/A'}\n` +
      `💼 Designation: ${userData.designation || 'N/A'}\n` +
      `📧 Email: ${userData.email || 'N/A'}\n` +
      `📊 Status: ${userData.status || 'N/A'}\n\n` +
      `Type HELP to see available commands.`;
  }

  // Unknown command
  else {
    responseMessage = `❓ Unknown command: "${messageText}"\n\nType HELP to see available commands.`;
  }

  // Always add timestamp fields when updating
  if (shouldUpdate) {
    fieldsToUpdate.lastMessage = messageText;
    fieldsToUpdate.lastMessageDate = new Date().toISOString();
    fieldsToUpdate.updatedAt = new Date().toISOString();
  }

} catch (error) {
  responseMessage = `❌ Error processing command: ${error.message}\n\nType HELP for available commands.`;
}

// Return data with proper structure - only include fields that have values
const outputData = {
  phoneNumber: phoneNumber,
  responseMessage: responseMessage,
  hasUpdate: shouldUpdate
};

// Only add fields that exist in fieldsToUpdate
if (shouldUpdate) {
  Object.keys(fieldsToUpdate).forEach(key => {
    if (fieldsToUpdate[key] !== undefined && fieldsToUpdate[key] !== null) {
      outputData[key] = fieldsToUpdate[key];
    }
  });
}

return {
  json: outputData
};

// Get the data from previous node
const inputData = $input.item.json;

// Build the update object with ONLY fields that have actual values
const updateFields = {};

// List of fields that can be updated
const allowedFields = ['name', 'designation', 'workingKnowledge', 'email', 'lastMessage', 'lastMessageDate', 'updatedAt'];

// Only include fields that have actual values (not undefined, not null, not empty string)
allowedFields.forEach(field => {
  if (inputData[field] !== undefined && 
      inputData[field] !== null && 
      inputData[field] !== '') {
    updateFields[field] = inputData[field];
  }
});

// IMPORTANT: Create a comma-separated list of field names for MongoDB
const fieldsList = Object.keys(updateFields).join(',');

// Return formatted data for MongoDB with dynamic field list
return {
  json: {
    phoneNumber: inputData.phoneNumber,
    responseMessage: inputData.responseMessage,
    fieldsToUpdate: fieldsList,  // This will be used in MongoDB node
    ...updateFields
  }
};
